// Arma lo que se guarda en la memoria (sin DNI ni apellido)
const mem = $('Memoria lista').first().json;
const mgr = $('Manager JSON').first().json.output;

let prev = {};
try {
  prev = JSON.parse($('Buscar memoria').first().json.fields?.['Datos clave'] || '{}');
} catch (e) { prev = {}; }

let id_paciente = prev.id_paciente || '';
if ($('Paciente existente').isExecuted) id_paciente = $('Paciente existente').first().json.id_paciente;
if ($('Paciente nuevo').isExecuted) id_paciente = $('Paciente nuevo').first().json.id_paciente;

const nombre = mgr.nombre || prev.nombre || '';

const estados = {
  IDENTIFICACION: 'IDENTIFICADO',
  TURNOS: 'TURNO EN CURSO',
  CONSULTAS: 'CONSULTA RESUELTA',
  HUMANO: 'DERIVADO A HUMANO',
};
const estado = estados[mgr.ruta] || mem.estado || 'NUEVO';

const mensajes = Number(mem.mensajes || 0) + 1;

return [{
  json: {
    record_id: mem.record_id,
    estado,
    mensajes,
    datos_clave: JSON.stringify({ ...prev, id_paciente, nombre }),
    last_summary: mem.last_summary,
  }
}];

