// Verifica el JSON del resumen y borra datos personales que se hayan colado
const prep = $('Preparar memoria').first().json;
const apellido = String($('Manager JSON').first().json.output.apellido || '').trim();

let r = null;
try {
  r = JSON.parse(String($input.first().json.text ?? '').replace(/```json|```/g, '').trim());
} catch (e) { r = null; }

const valido = r && typeof r.asunto_principal === 'string'
  && Array.isArray(r.puntos_clave) && typeof r.accion_requerida === 'string';

const limpiar = (texto) => {
  let t = String(texto).replace(/\b\d{7,8}\b/g, '[dato omitido]');
  if (apellido) {
    const escapado = apellido.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    t = t.replace(new RegExp(escapado, 'gi'), '').replace(/\s{2,}/g, ' ').trim();
  }
  return t;
};

let resumen = prep.last_summary;
if (valido) {
  resumen = JSON.stringify({
    asunto_principal: limpiar(r.asunto_principal),
    puntos_clave: r.puntos_clave
      .filter(p => !/^paciente\s*:/i.test(String(p)))
      .map(limpiar),
    accion_requerida: limpiar(r.accion_requerida),
  });
}

return [{
  json: {
    record_id: prep.record_id,
    estado: prep.estado,
    datos_clave: prep.datos_clave,
    resumen,
    mensajes: valido ? 0 : prep.mensajes,
  }
}];
